?>
<?= U::heading('Deliveries', 'Priority chooses which ready orders go together; SSTF orders the stops from the station, nearest first.', U::btn('Order queue', '/station-admin/orders', 'secondary', 'orders')) ?>
<?php if (isset($live['error'])): ?><section class="panel p-6" role="alert"><?= U::e($live['error']) ?></section><?php return; endif;
$pv = $live['preview']; $proposal = $pv['proposal'] ?? null; $active = array_filter($live['trips'], static fn (array $t): bool => $t['status'] === 'active');
$freeRiders = array_values(array_filter($live['riders'], static fn (array $r): bool => $r['free'])); ?>
<div class="mb-5 grid grid-cols-2 gap-3 xl:grid-cols-4"><?= U::stat('Active trips', (string) count($active), 'truck', 'blue', 'On the road now') ?><?= U::stat('Ready to dispatch', (string) count($pv['eligible'] ?? []), 'check', 'green', 'Due within the hour') ?><?= U::stat('Free riders', (string) count($freeRiders), 'users', 'violet', 'Can take the next trip') ?><?= U::stat('Cash to verify', (string) count($live['payments']), 'credit', 'amber', 'Collected, not yet checked') ?></div>
<div class="grid gap-5 xl:grid-cols-[minmax(0,1fr)_380px]"><div class="space-y-5">
<section class="panel p-4 md:p-5" id="dispatch"><?= U::title('Next trip', 'truck', 'mb-3') ?>
<?php foreach ($pv['warnings'] ?? [] as $w): ?><p class="mb-2 rounded-lg border border-amber-200 bg-amber-50 p-3 text-sm text-amber-900"><strong><?= U::e($w['order_no']) ?></strong> (<?= (int) $w['load'] ?> units): <?= U::e($w['message']) ?> It stays ready until a suitable vehicle is free or the order is revised.</p><?php endforeach ?>
<?php if (!empty($pv['message'])): ?><p class="rounded-lg bg-foam p-4 text-sm"><?= U::e($pv['message']) ?></p>
