<?php else: ?>
<?= F::open('/station-admin/dispatch', [], ['class' => 'space-y-4']) ?>
<div class="grid gap-3 sm:grid-cols-2"><?= U::select('Rider', 'rider_id', [$proposal['rider_id'] => $proposal['rider_name'] . ' · carries ' . $proposal['capacity'] . ' · ' . $proposal['trips_today'] . ' trip(s) today'] + array_column(array_map(static fn (array $r): array => ['id' => $r['rider_id'], 'label' => $r['name'] . ' · carries ' . $r['capacity'] . ' · ' . $r['trips_today'] . ' trip(s) today'], $pv['other_riders']), 'label', 'id'), $proposal['rider_id']) ?><div class="rounded-lg bg-mist p-3 text-sm"><p class="text-muted">Barangay</p><p class="font-semibold"><?= U::e($proposal['barangay'] ?? 'Not set') ?></p><p class="mt-1 text-muted">Load <?= (int) $proposal['load'] ?> of <?= (int) $proposal['capacity'] ?> · about <?= U::e(number_format((float) $proposal['planned_km'], 1)) ?> km of stops</p></div></div>
<fieldset><legend class="label">Stops in visiting order (uncheck to leave an order for later)</legend><ol class="space-y-2"><?php foreach ($proposal['stops'] as $s): ?>
<li class="flex flex-wrap items-center gap-3 rounded-lg border border-line p-3"><input type="checkbox" name="order_ids[]" value="<?= U::e($s['order_id']) ?>" checked class="size-4 accent-cyan-600" aria-label="Include <?= U::e($s['order_no']) ?>"><span class="flex size-7 items-center justify-center rounded-full bg-water text-sm font-bold text-white"><?= (int) $s['sequence'] ?></span><span class="min-w-0 flex-1"><strong><?= U::e($s['order_no']) ?></strong> · <?= U::e($s['customer_name'] ?? '') ?><span class="block text-xs text-muted"><?= (int) $s['load'] ?> units · <?= U::e(number_format((float) $s['leg_km'], 2)) ?> km from the previous point · <?= U::e(number_format((float) $s['station_km'], 2)) ?> km from the station</span></span><?= $s['overdue'] ? U::badge('Overdue', 'red') : '' ?><span class="text-xs font-semibold">P <?= (int) $s['score'] ?></span></li>
<?php endforeach ?></ol></fieldset>
<?php $overdue = array_filter($proposal['stops'], static fn (array $s): bool => (bool) $s['overdue']); if ($overdue !== []): ?><details class="rounded-lg border border-line p-3 text-sm"><summary class="cursor-pointer font-semibold">Move one overdue stop to the front</summary><div class="mt-3 grid gap-3 sm:grid-cols-2"><?= U::select('Overdue stop', 'front_order_id', ['' => 'Keep SSTF order'] + array_column(array_map(static fn (array $s): array => ['id' => $s['order_id'], 'no' => $s['order_no']], $overdue), 'no', 'id')) ?><?= U::field('Reason', 'front_reason', '', 'text', ['maxlength' => '300', 'placeholder' => 'Waited over two hours']) ?></div></details><?php endif ?>
<p class="text-xs text-muted">The database checks every order, the rider and the vehicle capacity again when you dispatch, and recalculates the stop order for the orders you keep. SSTF shortens trips but does not guarantee the shortest road route.</p>
