<?php endif ?></section>
<section class="panel p-4 md:p-5"><?= U::title('Trips', 'clock', 'mb-3') ?><?php if ($live['trips'] === []): ?><p class="p-4 text-center text-muted">No trips this week.</p><?php else: ?><?= U::table(['Trip', 'Rider', 'Barangay', 'Load', 'Stops', 'Status', ''], array_map(static fn (array $t): array => ['<strong>Trip ' . (int) $t['trip_no'] . '</strong><span class="block text-xs text-muted">' . U::e(S::time($t['dispatched_at'], 'M j, g:i A')) . '</span>', U::e($t['rider_name']), U::e($t['barangay'] ?? ''), (int) $t['load_units'] . ' / ' . (int) $t['capacity'], (int) $t['resolved'] . ' / ' . (int) $t['stops'] . ' done', U::badge($t['status'] === 'active' ? 'On the road' : 'Closed', $t['status'] === 'active' ? 'blue' : 'green'), U::btn('View', '/station-admin/trip?trip=' . $t['id'], 'secondary', 'eye', ['class' => 'btn-sm'])], $live['trips'])) ?><?php endif ?></section>
</div><aside class="space-y-5">
<section class="panel p-4 md:p-5"><?= U::title('Cash to verify', 'credit', 'mb-3') ?><?php if ($live['payments'] === []): ?><p class="text-sm text-muted">All collected cash is verified.</p><?php endif ?>
