<section class="panel p-4 md:p-5"><?= U::title('Riders and vehicles', 'users', 'mb-3') ?><?php if ($live['riders'] === []): ?><p class="text-sm text-muted">Add riders on the Drivers page.</p><?php endif ?>
<?php foreach ($live['riders'] as $r): ?><details class="mb-2 rounded-lg border border-line p-3 text-sm"><summary class="flex cursor-pointer items-center justify-between gap-2"><span><strong><?= U::e($r['name']) ?></strong> · <?= U::e($r['vehicle']) ?>, carries <?= (int) $r['capacity'] ?></span><?= !$r['enabled'] ? U::badge('Off', 'gray') : ($r['free'] ? U::badge('Free', 'green') : U::badge('On a trip', 'blue')) ?></summary>
<?= F::open('/station-admin/riders/save', ['rider_id' => $r['id'], 'expected_version' => $r['version']], ['class' => 'mt-3 grid gap-2']) ?><?= U::select('Vehicle', 'vehicle', ['Motorcycle with sidecar' => 'Motorcycle with sidecar', 'Tricycle' => 'Tricycle', 'Delivery van' => 'Delivery van'], $r['vehicle'], ['id' => 'vehicle-' . $r['id']]) ?><?= U::field('Plate number', 'plate_number', $r['plate_number'], 'text', ['id' => 'plate-' . $r['id'], 'required' => true, 'maxlength' => '20']) ?><?= U::field('Capacity (containers)', 'capacity', (string) $r['capacity'], 'number', ['id' => 'cap-' . $r['id'], 'min' => '1', 'max' => '100', 'required' => true]) ?><label class="flex items-center gap-2"><input type="checkbox" name="enabled" value="1" <?= $r['enabled'] ? 'checked' : '' ?> class="accent-cyan-600">Available for dispatch</label><?= U::btn('Save', '', 'secondary', 'check', ['type' => 'submit', 'class' => 'btn-sm']) ?></form></details><?php endforeach ?></section>
